    private void JavaScript_DocumentCookie_Internal(
    string String)
    {
        bool Boolean
        = String
        .Length > 0;

        switch (Boolean)
        {
            case true:
                {
                    JToken JToken
                    = JObject
                    .Parse(String);

                    ManageJObject
                    .Merge(
                    JToken, 
                    new JsonMergeSettings
                    {
                        MergeArrayHandling 
                        = MergeArrayHandling
                        .Replace
                    });
                }
                break;
        }

        JavaScript_DocumentCookie_Internal_isPresent
        = true;
    }

