    private async UniTask<string> JavaScript_ClientAgent(
    JToken JToken)
    {
        JavaScript_ClientAgent_Error_Boolean
        = false;

        string String
        = JToken
        .ToString(
        Formatting
        .None);

        JavaScript_ClientAgent
        (String);

        String
        = String
        .Empty;

        while (true)
        {
            bool Boolean
            = JavaScript_ClientAgent_Error_Boolean

            || String
            .IsNullOrEmpty
            (JavaScript_ClientAgent_Internal_Data)
            == false;

            if (Boolean)
            {
                {
                    String
                    = JavaScript_ClientAgent_Internal_Data;

                    JavaScript_ClientAgent_Internal_Data
                    = String
                    .Empty;
                }

                break;
            }

            await UniTask
            .Yield(
            PlayerLoopTiming
            .LastUpdate);
        }

        return String;
    }

    string JavaScript_ClientAgent_Internal_Data
    = String
    .Empty;

