#endif

        {
            {
                Transform Transform
                = Canvas
                .transform.Find("Widget[Object]")
                .transform.Find("Panel[Object]")
                .transform;

                foreach (Transform _Transform
                in Transform)
                {
                    string String
                    = _Transform
                    .gameObject.name;

                    Transform
                    = _Transform.Find("List[Object]")
                    .transform.Find("Handle[Event]");

                    bool Boolean
                    = Transform
                    != null;

                    switch (Boolean)
                    {
                        case true:
                            {
                                float Index
                                = 0f;

                                RectTransform RectTransform
                                = _Transform
                                .GetComponent<RectTransform>();

                                float Length
                                = RectTransform
                                .anchoredPosition.y;

                                EventTrigger EventTrigger
                                = Transform
                                .GetComponent<EventTrigger>();

                                {
                                    EventTrigger.Entry EventTriggerEntry
                                    = new EventTrigger.Entry();

                                    EventTriggerEntry.eventID
                                    = EventTriggerType.Drag;

                                    EventTriggerEntry
                                    .callback
                                    .AddListener((eventData) =>
                                    {
                                        LayoutElement LayoutElement
                                        = _Transform
                                        .GetComponent<LayoutElement>();

                                        LayoutElement
                                        .ignoreLayout
                                        = true;

                                        bool Boolean
                                        = Pointer
                                        .current
                                        != null

                                        && Pointer
                                        .current
                                        .press
                                        .isPressed;

                                        switch (Boolean)
                                        {
                                            case true:
                                                {
                                                    Vector2 PosVector2
                                                    = Pointer
                                                    .current
                                                    .position
                                                    .ReadValue();

                                                    Boolean
                                                    = Index
                                                    != 0f;

                                                    switch (Boolean)
                                                    {
                                                        case true:
                                                            {
                                                                float FadeMulFloat
                                                                = 0.005f;

                                                                float TouchAcrFloat
                                                                = 12f;

                                                                {
                                                                    Boolean
                                                                    = Index <=
                                                                    PosVector2.y

                                                                    && RectTransform
                                                                    .anchoredPosition.y
                                                                    < Length;

                                                                    switch (Boolean)
                                                                    {
                                                                        case true:
                                                                            {
                                                                                {
                                                                                    CanvasGroup CanvasGroup
                                                                                    = _Transform
                                                                                    .GetComponent<CanvasGroup>();

                                                                                    CanvasGroup
                                                                                    .alpha +=
                                                                                    FadeMulFloat;
                                                                                }

                                                                                {
                                                                                    Vector2 Vector2
                                                                                    = RectTransform
                                                                                    .anchoredPosition;

                                                                                    Vector2.y
                                                                                    += TouchAcrFloat;

                                                                                    RectTransform
                                                                                    .anchoredPosition
                                                                                    = Vector2;
                                                                                }
                                                                            }
                                                                            break;
                                                                    }
                                                                }

                                                                {
                                                                    Boolean
                                                                    = Index >=
                                                                    PosVector2.y;

                                                                    switch (Boolean)
                                                                    {
                                                                        case true:
                                                                            {
                                                                                {
                                                                                    CanvasGroup CanvasGroup
                                                                                    = _Transform
                                                                                    .GetComponent<CanvasGroup>();

                                                                                    CanvasGroup
                                                                                    .alpha -=
                                                                                    FadeMulFloat;
                                                                                }

                                                                                {
                                                                                    Vector2 Vector2
                                                                                    = RectTransform
                                                                                    .anchoredPosition;

                                                                                    Vector2.y
                                                                                    -= TouchAcrFloat;

                                                                                    RectTransform
                                                                                    .anchoredPosition
                                                                                    = Vector2;
                                                                                }
                                                                            }
                                                                            break;
                                                                    }
                                                                }
                                                            }
                                                            break;
                                                    }

                                                    Index
                                                    = PosVector2.y;
                                                }
                                                break;
                                        }
                                    });

                                    EventTrigger.triggers
                                    .Add(EventTriggerEntry);
                                }

                                {
                                    EventTrigger.Entry EventTriggerEntry
                                    = new EventTrigger.Entry();

                                    EventTriggerEntry.eventID
                                    = EventTriggerType.EndDrag;

                                    EventTriggerEntry
                                    .callback
                                    .AddListener((eventData) =>
                                    {
                                        Index
                                        = 0f;

                                        {
                                            CanvasGroup CanvasGroup
                                            = _Transform
                                            .GetComponent<CanvasGroup>();

                                            CanvasGroup
                                            .alpha = 1f;
                                        }

                                        {
                                            LayoutElement LayoutElement
                                            = _Transform
                                            .GetComponent<LayoutElement>();

                                            LayoutElement
                                            .ignoreLayout
                                            = false;
                                        }

                                        {
                                            Boolean
                                            = RectTransform
                                            .anchoredPosition.y
                                            <= (Length - 235f);

                                            switch (Boolean)
                                            {
                                                case true:
                                                    {
                                                        Transform Transform
                                                        = Canvas
                                                        .transform.Find("Widget[Object]")
                                                        .transform.Find("Panel[Object]")
                                                        .transform;

                                                        foreach (Transform _Transform
                                                        in Transform)
                                                        {
                                                            _Transform
                                                            .gameObject
                                                            .SetActive(false);
                                                        }
                                                    }
                                                    break;
                                            }
                                        }
                                    });

                                    EventTrigger.triggers
                                    .Add(EventTriggerEntry);
                                }
                            }
                            break;
                    }
                }
            }
        }

