    bool Manage_Cancellation
    = false;
    private async UniTask Manage(
    JToken PJToken)
    {
        Manage_Cancellation
        = false;

        switch (
        (string)PJToken
        ["Event"])
        {
            case "Cookie":
                {
                    switch (
                    (string)
                    PJToken
                    ["Task"])
                    {
                        case "Get":
                            {
#if !UNITY_EDITOR
                                JavaScript_DocumentCookie(
                                "Get", 
                                null);
#else
                                string String
                                = "Cookie";

                                bool Boolean
                                = PlayerPrefs
                                .HasKey(String);

                                switch (Boolean)
                                {
                                    case true:
                                        {
                                            String
                                            = PlayerPrefs
                                            .GetString(String);

                                            JToken JToken
                                            = JObject
                                            .Parse(String);

                                            ManageJObject
                                            .Merge(
                                            JToken, 
                                            new JsonMergeSettings
                                            {
                                                MergeArrayHandling 
                                                = MergeArrayHandling
                                                .Replace
                                            });
                                        }
                                        break;
                                }
#endif
                            }
                            break;
                        case "Set":
                            {
                                JToken JToken
                                = ManageJObject;

                                string String
                                = JToken
                                .ToString(
                                Formatting
                                .None);

#if !UNITY_EDITOR
                                JavaScript_DocumentCookie(
                                "Set",
                                String);
#else
                                PlayerPrefs
                                .SetString(
                                "Cookie",
                                String);

                                PlayerPrefs
                                .Save();
#endif
                            }
                            break;
                    }
                }
                break;
            case "Language":
                {
                    Http Http
                    = new Http();

                    {
                        StringBuilder StringBuilder
                        = new StringBuilder();

                        StringBuilder
                        .Append(Domain);

#if WebAuth
                        StringBuilder
                        .Append("/auth");
#elif WebAccessibility
                        StringBuilder
                        .Append("/accessibility");
#endif
                        StringBuilder
                        .Append("/data");
                        StringBuilder
                        .Append("/lang/");

                        string String
                        = (string)
                        PJToken["Lang"];

                        StringBuilder
                        .Append(String);

                        String
                        = StringBuilder
                        .ToString();

                        Http.Url
                        = String;
                    }

#if !WebAccessibility
                    Http.HttpCache
                    = Http
                    .Cache
                    .Never;
#endif

                    Http.HttpPriority
                    = Http
                    .Priority
                    .Highest;

                    byte[] Bytes
                    = await Http
                    .GetAsync();

                    bool Boolean
                    = Bytes
                    .Length > 0;

                    switch (Boolean)
                    {
                        case true:
                            {
                                string String
                                = Encoding.UTF8
                                .GetString(Bytes);

                                JObject JObject
                                = JObject
                                .Parse(String);

#if UNITY_EDITOR
                                String
                                = JObject
                                .ToString
                                (Formatting
                                .Indented);

                                Debug
                                .Log(String);
#endif

                                IEnumerable
                                <TextMeshProUGUI> IEnumerable
                                = Canvas
                                .GetComponentsInChildren
                                <TextMeshProUGUI>(true);

                                {
                                    int Delay
                                    = 0;

                                    foreach (
                                    TextMeshProUGUI
                                    TextMeshProUGUI
                                    in IEnumerable)
                                    {
                                        if (Manage_Cancellation)
                                        { break; }

                                        String
                                        = TextMeshProUGUI
                                        .text;

                                        Boolean
                                        = new string[]
                                        {
                                            "Title",
                                            "Label",
                                            "Text"
                                        }.Any(
                                        x =>
                                        x ==
                                        String)
                                        == false

                                        && String
                                        .Any(
                                        x =>
                                        char
                                        .IsLetter(x))

                                        && String
                                        .Length > 0;

                                        switch (Boolean)
                                        {
                                            case true:
                                                {
                                                    Bytes
                                                    = Encoding.
                                                    UTF8.GetBytes(String);

                                                    Bytes
                                                    = XxHash64
                                                    .Hash(Bytes);

                                                    string Index
                                                    = Convert
                                                    .ToBase64String(Bytes);

                                                    Boolean
                                                    = JObject
                                                    .ContainsKey(Index);

                                                    switch (Boolean)
                                                    {
                                                        case true:
                                                            {
                                                                JToken JToken
                                                                = JObject[Index];

                                                                String
                                                                = (string)JToken;

                                                                TextMeshProUGUI
                                                                .text
                                                                = String;
                                                            }
                                                            break;
                                                    }
                                                }
                                                break;
                                        }

                                        {
                                            if (++Delay % 100 == 0)
                                            {
                                                await UniTask
                                                .Yield(
                                                PlayerLoopTiming
                                                .Update);
                                            }
                                        }
                                    }
                                }
                            }
                            break;
                    }
                }
                break;
        }
    }
#endif

