    private bool Widget_Auth_Cancellation
    = false;

    JToken Widget_Auth_Task_JToken
    = new JObject
    {
        ["Panel"]
        = String
        .Empty
    };

    private async UniTask Widget_Auth_Task(
    JToken PJToken
    )
    {
        Transform Transform
        = Canvas
        .transform.Find("Widget[Object]")
        .transform.Find("Panel[Object]")
        .transform.Find("Auth[Object]")
        .transform.Find("List[Object]")
        .transform.Find("Panel[Object]")
        .transform;

        {
            foreach (Transform _Transform
            in Transform)
            {
                _Transform
                .gameObject
                .SetActive(false);
            }

            Transform
            = Transform
            .Find("Progress[Object]")
            .transform;

            Transform
            .gameObject
            .SetActive(true);

            Animator Animator
            = Transform
            .GetComponent<Animator>();

            await Animate
            (Animator);
        }

        {
            switch (
            (string)PJToken
            ["Event"])
            {
                case "PhotoID":
                    {
                        Http Http
                        = new Http();

                        {
                            StringBuilder StringBuilder
                            = new StringBuilder();

                            StringBuilder
                            .Append(EndPoint);

                            StringBuilder
                            .Append("/Request");

                            string String
                            = StringBuilder
                            .ToString();

                            Http.Url
                            = String;
                        }

                        {
                            string String
                            = new JObject
                            {
                                ["Auth"]
                                = new JObject
                                {
                                    ["Associate"]
                                    = new JObject
                                    {
                                        ["ID"]
                                        = (int)
                                        PJToken
                                        ["ID"]
                                    }
                                }
                            }
                            .ToString(
                            Formatting
                            .None);

                            Http.Form
                            = String;
                        }

                        Http.HttpCache
                        = Http
                        .Cache
                        .Never;

                        Http.HttpPriority
                        = Http
                        .Priority
                        .Highest;

                        byte[] Bytes
                        = await Http
                        .PostAsync();

                        bool Boolean
                        = Bytes
                        .Length > 0;

                        switch (Boolean)
                        {
                            case true:
                                {
                                    string String
                                    = Encoding.UTF8
                                    .GetString(Bytes);

                                    JToken JToken
                                    = JObject
                                    .Parse(String);

#if UNITY_EDITOR
                                    String
                                    = JToken
                                    .ToString
                                    (Formatting
                                    .Indented);

                                    Debug
                                    .Log(String);
#endif

                                    string Path
                                    = ".Auth"
                                    + ".Associate"
                                    + ".ID"
                                    + ".Error";

                                    Boolean
                                    = JToken
                                    .SelectToken(
                                    Path,
                                    errorWhenNoMatch: false)
                                    == null;

                                    switch (Boolean)
                                    {
                                        case true:
                                            {
                                                {
                                                    ManageJObject
                                                    ["Credentials"]
                                                    ["Associate"]
                                                    ["UUID"]

                                                    = (Guid)
                                                    JToken
                                                    ["Auth"]
                                                    ["Associate"]
                                                    ["ID"]
                                                    ["UUID"];

                                                    ManageJObject
                                                    ["Credentials"]
                                                    ["Associate"]
                                                    ["Access-Token"]

                                                    = (Guid)
                                                    JToken
                                                    ["Auth"]
                                                    ["Associate"]
                                                    ["ID"]
                                                    ["Access-Token"];

                                                    ManageJObject
                                                    ["Credentials"]
                                                    ["Associate"]
                                                    ["Time"]

                                                    = (DateTime)
                                                    JToken
                                                    ["Auth"]
                                                    ["Associate"]
                                                    ["ID"]
                                                    ["Time"];

                                                    await
                                                    Manage(
                                                    new JObject
                                                    {
                                                        ["Event"]
                                                        = "Cookie",

                                                        ["Task"]
                                                        = "Set"
                                                    });
                                                }

                                                {
#if !UNITY_EDITOR
                                                    StringBuilder StringBuilder
                                                    = new StringBuilder();

                                                    StringBuilder
                                                    .Append(Domain);

                                                    StringBuilder
                                                    .Append("/accessibility");

                                                    String
                                                    = StringBuilder
                                                    .ToString();

                                                    JavaScript_Redirect
                                                    (String);
#else
                                                    StringBuilder StringBuilder
                                                    = new StringBuilder();

                                                    StringBuilder
                                                    .Append("Assets");
                                                    StringBuilder
                                                    .Append("/Module");
                                                    StringBuilder
                                                    .Append("/Web");
                                                    StringBuilder
                                                    .Append("/WebAccessibility(Module).unity");

                                                    Path
                                                    = StringBuilder
                                                    .ToString();

                                                    {
                                                        EditorApplication
                                                        .isPlaying
                                                        = false;

                                                        while (
                                                        EditorApplication
                                                        .isPlaying)
                                                        {
                                                            await UniTask
                                                            .Yield();
                                                        }

                                                        EditorSceneManager
                                                        .OpenScene(Path);
                                                    }
#endif
                                                }
                                            }
                                            break;
                                        case false:
                                            {
                                                Transform
                                                = Canvas
                                                .transform.Find("Widget[Object]")
                                                .transform.Find("Panel[Object]")
                                                .transform.Find("Auth[Object]")
                                                .transform.Find("List[Object]")
                                                .transform.Find("Panel[Object]")
                                                .transform.Find("PhotoID[Object]")
                                                .transform.Find("Content[Object]")
                                                .transform.Find("Error[Object]")
                                                .transform;

                                                Transform
                                                .gameObject
                                                .SetActive(true);

                                                TextMeshProUGUI TextMeshProUGUI
                                                = Transform
                                                .Find("Label[Text]")
                                                .GetComponent<TextMeshProUGUI>();

                                                String
                                                = (string)
                                                JToken
                                                ["Auth"]
                                                ["Associate"]
                                                ["ID"]
                                                ["Error"];

                                                switch (String)
                                                {
                                                    case "ID-is-Invalid":
                                                        {
                                                            String
                                                            = "ID is invalid";
                                                        }
                                                        break;
                                                    case "Password-is-Required":
                                                        {
                                                            {
                                                                Widget_Auth_Task_JToken
                                                                ["Panel"]
                                                                = "PhotoID";
                                                            }

                                                            {
                                                                Transform
                                                                = Canvas
                                                                .transform.Find
                                                                ("Widget[Object]")
                                                                .transform;

                                                                Transform
                                                                .gameObject
                                                                .SetActive(true);

                                                                {
                                                                    Transform
                                                                    = Transform.Find
                                                                    ("Panel[Object]")
                                                                    .transform;

                                                                    foreach (Transform _Transform
                                                                    in Transform)
                                                                    {
                                                                        _Transform
                                                                        .gameObject
                                                                        .SetActive(false);
                                                                    }

                                                                    {
                                                                        Transform
                                                                        = Transform.Find
                                                                        ("Auth[Object]")
                                                                        .transform;

                                                                        Transform
