    private WebCamTexture Widget_Auth_PhotoID_WebCamTexture;
    private RenderTexture Widget_Auth_PhotoID_RenderTexture;
    private UniTask Widget_Auth_PhotoID_AsyncOperation;
    private Dictionary<int, int> Widget_Auth_PhotoID_Dictionary
    = new Dictionary<int, int>();
    private IBarcodeReader Widget_Auth_PhotoID_IBarcodeReader
    = new BarcodeReader
    {
        AutoRotate
        = true,

        TryInverted
        = true,

        Options
        = new ZXing.Common.DecodingOptions
        {
            PossibleFormats
            = new[]
            {
                BarcodeFormat
                .UPC_E
            },

            TryHarder
            = true
        }
    };
    private async UniTask Widget_Auth_PhotoID_Task()
    {
        Transform Transform
        = Canvas
        .transform.Find("Widget[Object]")
        .transform.Find("Panel[Object]")
        .transform.Find("Auth[Object]")
        .transform.Find("List[Object]")
        .transform.Find("Panel[Object]")
        .transform;

        {
            foreach (Transform _Transform
            in Transform)
            {
                _Transform
                .gameObject
                .SetActive(false);
            }

            Transform
            = Transform
            .Find("Progress[Object]")
            .transform;

            Transform
            .gameObject
            .SetActive(true);

            Animator Animator
            = Transform
            .GetComponent<Animator>();

            await Animate
            (Animator);
        }

        {
            {
                bool Boolean
                = Widget_Auth_PhotoID_RenderTexture
                == null;

                switch (Boolean)
                {
                    case true:
                        {
                            Widget_Auth_PhotoID_RenderTexture
                            = new RenderTexture(
                            800,
                            800,
                            16);

                            Widget_Auth_PhotoID_RenderTexture
                            .Create();

                            RawImage RawImage
                            = Transform
                            .parent.Find("PhotoID[Object]")
                            .transform.Find("Content[Object]")
                            .transform.Find("Camera[Object]")
                            .transform.Find("Feed[RawImage]")
                            .GetComponent<RawImage>();

                            RawImage
                            .texture
                            = Widget_Auth_PhotoID_RenderTexture;
                        }
                        break;
                }
            }
        }

        {
            Transform
            = Transform
            .parent;

            foreach (Transform _Transform
            in Transform)
            {
                _Transform
                .gameObject
                .SetActive(false);
            }

            Transform
            = Transform.Find("PhotoID[Object]")
            .transform;

            Transform
            .gameObject
            .SetActive(true);

            Animator Animator
            = Transform
            .GetComponent<Animator>();

            await Animate
            (Animator);

            {
                Widget_Auth_PhotoID_WebCamTexture
                .Play();

                while (
                Transform
                .gameObject
                .activeInHierarchy)
                {
                    int Width
                    = Widget_Auth_PhotoID_WebCamTexture
                    .width;

                    int Height
                    = Widget_Auth_PhotoID_WebCamTexture
                    .height;

                    Array Array
                    = new Color32
                    [Width * Height];

                    bool Boolean
                    = Widget_Auth_PhotoID_WebCamTexture
                    .didUpdateThisFrame

                    && Widget_Auth_PhotoID_WebCamTexture
                    .width
                    > 16

                    && Widget_Auth_PhotoID_WebCamTexture
                    .height
                    > 16;

                    switch (Boolean)
                    {
                        case true:
                            {
                                {
                                    Boolean
                                    = Widget_Auth_PhotoID_AsyncOperation
                                    .Status
                                    .IsCompleted();

                                    switch (Boolean)
                                    {
                                        case true:
                                            {
                                                Widget_Auth_PhotoID_WebCamTexture
                                                .GetPixels32(
                                                (Color32[])Array);

                                                Graphics
                                                .Blit(
                                                Widget_Auth_PhotoID_WebCamTexture,
                                                Widget_Auth_PhotoID_RenderTexture);

                                                Widget_Auth_PhotoID_AsyncOperation
                                                = UniTask
                                                .Create(async () =>
                                                {
                                                    int Width
                                                    = Widget_Auth_PhotoID_WebCamTexture
                                                    .width;

                                                    int Height
                                                    = Widget_Auth_PhotoID_WebCamTexture
                                                    .height;

                                                    Result Result
                                                    = Widget_Auth_PhotoID_IBarcodeReader
                                                    .Decode(
                                                    (Color32[])Array,
                                                    Width,
                                                    Height);

                                                    Boolean
                                                    = Result
                                                    != null;

                                                    switch (Boolean)
                                                    {
                                                        case true:
                                                            {
                                                                string String
                                                                = Result
                                                                .Text;

                                                                int Index
                                                                = int
                                                                .Parse(String);

                                                                int Length
                                                                = String
                                                                .Length;

                                                                Boolean
                                                                = String
                                                                .All(
                                                                x =>
                                                                char
                                                                .IsNumber(x))

                                                                && Length
                                                                >= 8;

                                                                switch (Boolean)
                                                                {
                                                                    case true:
                                                                        {
                                                                            {
                                                                                Boolean
                                                                                = Widget_Auth_PhotoID_Dictionary
                                                                                .ContainsKey(Index)
                                                                                == false;

                                                                                switch (Boolean)
                                                                                {
                                                                                    case true:
                                                                                        {
                                                                                            Widget_Auth_PhotoID_Dictionary
                                                                                            .Add(
                                                                                            Index,
                                                                                            0);
                                                                                        }
                                                                                        break;
                                                                                }
                                                                            }

                                                                            {
                                                                                int Columns
                                                                                = Widget_Auth_PhotoID_Dictionary
                                                                                [Index];

                                                                                Columns
                                                                                ++;

                                                                                Widget_Auth_PhotoID_Dictionary
                                                                                [Index]
                                                                                = Columns;
                                                                            }
                                                                        }
                                                                        break;
                                                                }
                                                            }
                                                            break;
                                                    }
                                                });
                                            }
                                            break;
                                    }
                                }
                            }
                            break;
                    }

                    {
                        int Length
                        = Widget_Auth_PhotoID_Dictionary
                        .Count();

                        Boolean
                        = Length
                        > 0

                        && Widget_Auth_Cancellation
                        == false;

                        switch (Boolean)
                        {
                            case true:
                                {
                                    KeyValuePair<int, int> KeyValuePair
                                    = Widget_Auth_PhotoID_Dictionary
                                    .Aggregate(
                                    (x, y)
                                    =>
                                    x.Value
                                    > y.Value
                                    ? x : y);

                                    int Columns
                                    = KeyValuePair
                                    .Value;

                                    Boolean
                                    = Columns
                                    >= 5;

                                    switch (Boolean)
                                    {
                                        case true:
                                            {
                                                int Index
                                                = KeyValuePair
                                                .Key;

                                                Widget_Auth_Cancellation
                                                = true;

                                                await
                                                Widget_Auth_Task(
                                                new JObject
                                                {
                                                    ["Event"]
                                                    = "PhotoID",

                                                    ["ID"]
                                                    = Index
                                                });

                                                Widget_Auth_PhotoID_Dictionary
                                                .Clear();
                                            }
                                            break;
                                    }
                                }
                                break;
                        }
                    }

                    await UniTask
                    .NextFrame();
                }

#if !UNITY_EDITOR
                Widget_Auth_PhotoID_WebCamTexture
                .Stop();
#endif

                Widget_Auth_PhotoID_Dictionary
                .Clear();
            }
        }
    }
