            bool Boolean
            = Bytes
            .Length > 0;

            switch (Boolean)
            {
                case true:
                    {
                        string String
                        = Encoding.UTF8
                        .GetString(Bytes);

#if UNITY_EDITOR
                        Debug
                        .Log(String);
#endif

                        {
                            Array Array
                            = String
                            .Split(
                            new[] {
                            "\r\n",
                            "\n",
                            "\r" },
                            StringSplitOptions
                            .None);

                            int Index
                            = 0;

                            int Columns
                            = Math
                            .Min
                            (6, Array
                            .Length);

                            {
                                foreach (Transform _Transform
                                in Transform)
                                {
                                    Boolean
                                    = _Transform
                                    .gameObject
                                    .activeSelf;

                                    switch (Boolean)
                                    {
                                        case true:
                                            {
                                                String
                                                = _Transform
                                                .gameObject
                                                .name;

                                                Boolean
                                                = String
                                                .EndsWith
                                                ("[Button]");

                                                switch (Boolean)
                                                {
                                                    case true:
                                                        {
                                                            Index
                                                            ++;
                                                        }
                                                        break;
                                                }
                                            }
                                            break;
                                    }
                                }

                                await
                                UniTask
                                .Yield();
                            }

                            Boolean
                            = Index
                            >= Array
                            .Length - 1;

                            switch (Boolean)
                            {
                                case true:
                                    {
                                        Columns
                                        = Array
                                        .Length
                                        - Index;
                                    }
                                    break;
                            }

                            ReadOnlyMemory<string> ReadOnlyMemory
                            = ((string[])Array)
                            .AsMemory(
                            Index,
                            Columns);

                            int Length
                            = ReadOnlyMemory
                            .Length;

                            for (int i = 0; i < Length; i++)
                            {
                                {
                                    String
                                    = ReadOnlyMemory
                                    .Span[i];

                                    StringBuilder StringBuilder
                                    = new StringBuilder();

                                    StringBuilder
                                    .Append(String);
                                    StringBuilder
                                    .Append("[Button]");

                                    String
                                    = StringBuilder
                                    .ToString();

                                    Boolean
                                    = Transform
                                    .Find(String)
                                    == null;

                                    switch (Boolean)
                                    {
                                        case true:
                                            {
                                                GameObject GameObject
                                                = Instantiate(
                                                Transform.Find
                                                ("Template[Button]")
                                                .gameObject,
                                                Transform);

                                                string _String
                                                = ReadOnlyMemory
                                                .Span[i];

                                                GameObject
                                                .name
                                                = String;

                                                GameObject
                                                .transform.localScale
                                                = new Vector3(1, 1, 1);

                                                Index
                                                = Transform.Find
                                                ("Progress[Object]")
