                                                        = GameObject
                                                        .transform.Find("Label[Text]")
                                                        .GetComponent<TextMeshProUGUI>();

                                                        TextMeshProUGUI
                                                        .text
                                                        = _String;
                                                    }
                                                }

                                                GameObject
                                                .SetActive(true);

                                                Animator Animator
                                                = GameObject
                                                .GetComponent<Animator>();

                                                await
                                                Animate(Animator);
                                            }
                                            break;
                                    }
                                }

                                {
                                    if (i % 100 == 0)
                                    {
                                        await UniTask
                                        .Yield(
                                        PlayerLoopTiming
                                        .Update);
                                    }
                                }
                            }
                        }
                    }
                    break;
            }
        }

        {
            Transform.Find
            ("Progress[Object]")
            .gameObject
            .SetActive(false);
        }

        Widget_Language_Cancellation
        = false;
