    bool Widget_Options_Options_Search_Cancellation
    = false;
    private async UniTask Widget_Options_Options_Search_Task(
    JToken PJToken)
    {
        Widget_Options_Options_Search_Cancellation
        = false;

        {
            Transform Transform
            = Canvas
            .transform.Find("Widget[Object]")
            .transform.Find("Panel[Object]")
            .transform.Find("Options[Object]")
            .transform.Find("List[Object]")
            .transform.Find("Panel[Object]")
            .transform.Find("Options[Object]")
            .transform.Find("Content[Object]")
            .transform.Find("List[Scroll-View]")
            .GetComponent<ScrollRect>()
            .content
            .transform;

            IEnumerable<Transform> IEnumerable
            = Transform
            .GetComponentsInChildren<Transform>
            (true)
            .Where(x
            =>
            x
            .gameObject
            .name
            .EndsWith
            ("[Object]")

            || x
            .gameObject
            .name
            .EndsWith
            ("[Button]"));

            List<Transform> List
            = new List<Transform>();

            foreach (Transform _Transform
            in IEnumerable)
            {
                if (Widget_Options_Options_Search_Cancellation)
                { break; }

                _Transform
                .gameObject
                .SetActive(true);

                bool Boolean
                = List
                .Any(
                x =>
                x == _Transform)
                == false;

                switch (Boolean)
                {
                    case true:
                        {
                            string String
                            = (string)PJToken
                            ["Search"];

                            String
                            = String
                            .ToLower();

                            Boolean
                            = String
                            .IsNullOrEmpty
                            (String)
                            == false;

                            switch (Boolean)
                            {
                                case true:
                                    {
                                        TextMeshProUGUI TextMeshProUGUI
                                        = _Transform.Find("Label[Text]")
                                        .GetComponent<TextMeshProUGUI>();

                                        Boolean
                                        = TextMeshProUGUI
                                        .text
                                        .ToLower()
                                        .Contains(String);

                                        _Transform
                                        .gameObject
                                        .SetActive(Boolean);
                                    }
                                    break;
                            }

                            {
                                switch (Boolean)
                                {
                                    case true:
                                        {
                                            {
                                                Boolean
                                                = _Transform
                                                .gameObject
                                                .name
                                                .EndsWith("[Object]");

                                                switch (Boolean)
                                                {
                                                    case true:
                                                        {
                                                            IEnumerable<Transform> _IEnumerable
                                                            = _Transform
                                                            .GetComponentsInChildren<Transform>
                                                            (true);

                                                            foreach (Transform __Transform
                                                            in _IEnumerable)
                                                            {
                                                                if (Widget_Options_Options_Search_Cancellation)
                                                                { break; }

                                                                __Transform
                                                                .gameObject
                                                                .SetActive(true);

                                                                List
                                                                .Add(__Transform);

                                                                await
                                                                UniTask
                                                                .Yield();
                                                            }
                                                        }
                                                        break;
                                                }
                                            }

                                            {
                                                Boolean
                                                = _Transform
                                                .gameObject
                                                .name
                                                .EndsWith("[Button]");

                                                switch (Boolean)
                                                {
                                                    case true:
                                                        {
                                                            Transform __Transform
                                                            = _Transform
                                                            .parent;

                                                            while (true)
                                                            {
                                                                if (Widget_Options_Options_Search_Cancellation)
                                                                { break; }

                                                                __Transform
                                                                .gameObject
                                                                .SetActive(true);

                                                                __Transform
                                                                = __Transform
                                                                .parent;

                                                                Boolean
                                                                = __Transform
                                                                == Transform;

                                                                List
                                                                .Add(__Transform);

                                                                if (Boolean)
                                                                { break; }

                                                                await
                                                                UniTask
                                                                .Yield();
                                                            }
                                                        }
                                                        break;
                                                }
                                            }
                                        }
                                        break;
                                }
                            }
                        }
                        break;
                }

                await
                UniTask
                .Yield();
            }
        }
    }

