            {
                Service_Stopwatch
                = System
                .Diagnostics
                .Stopwatch
                .StartNew();

                Stopwatch Stopwatch
                = @Service_Stopwatch;

                Stopwatch
                .Stop();

                while (true)
                {
                    bool Boolean
                    = Stopwatch
                    .IsRunning
                    == false;

                    switch (Boolean)
                    {
                        case true:
                            {
                                Stopwatch
                                .Restart();

                                {
                                    await Service
                                    (new JObject
                                    {
                                        ["Relay"]
                                        = new
                                        JObject()
                                    });
                                }

                                {
                                    await UniTask
                                    .Delay(
                                    TimeSpan
                                    .FromSeconds(2));
                                }
                            }
                            break;
                    }

                    await UniTask
                    .NextFrame();
                }
            }
        };

