    private async UniTask Service(
    JToken PJToken)
    {
        List<byte[]> List
        = @Queue_List;

        string String
        = PJToken
        .ToString
        (Formatting
        .None);

        byte[] Bytes
        = Encoding.UTF8
        .GetBytes
        (String);

        List
        .Add(Bytes);
    }

    private List<byte[]> Queue_List
    = new List<byte[]>();
    private async UniTask Queue()
    {
        WebSocket WebSocket
        = @Service_WebSocket;

        List<byte[]> List
        = @Queue_List;

        while (true)
        {
            bool Boolean
            = WebSocket
            != null;

            switch (Boolean)
            {
                case true:
                    {
                        Boolean
                        = WebSocket
                        .State ==
                        WebSocketState
                        .Open;

                        switch (Boolean)
                        {
                            case true:
                                {
                                    int Length
                                    = List
                                    .Count;

                                    Boolean
                                    = Length
                                    > 0;

                                    switch (Boolean)
                                    {
                                        case true:
                                            {
                                                for (int i = 0; i < Length; i++)
                                                {
                                                    Length
                                                    = List
                                                    .Count;

                                                    byte[] Bytes
                                                    = List
                                                    .ElementAt(i);

                                                    await WebSocket
                                                    .Send(Bytes);

                                                    await UniTask
                                                    .Delay(15);
                                                }

                                                List
                                                .Clear();
                                            }
                                            break;
                                    }
                                }
                                break;
                        }
                    }
                    break;
            }

            await
            UniTask
            .NextFrame();
        }
    }

