                                            .ToString();

                                            Dictionary<string, GameObject> Dictionary
                                            = @Environment_World_Addressables_Dictionary;

                                            Boolean
                                            = Dictionary
                                            .ContainsKey
                                            (Path)
                                            == false;

                                            switch (Boolean)
                                            {
                                                case true:
                                                    {
                                                        {
                                                            Boolean
                                                            = false;

                                                            Dictionary
                                                            .Add(Path,
                                                            null);
                                                        }

                                                        {
                                                            AsyncOperationHandle<GameObject>
                                                            AsyncOperationHandle
                                                            = Addressables
                                                            .LoadAssetAsync
                                                            <GameObject>(Path);

                                                            AsyncOperationHandle
                                                            .Completed
                                                            += async (Handle)
                                                            =>
                                                            {
                                                                Boolean
                                                                = Handle
                                                                .Status
                                                                == AsyncOperationStatus
                                                                .Succeeded;

                                                                switch (Boolean)
                                                                {
                                                                    case true:
                                                                        {
                                                                            {
                                                                                GameObject GameObject
                                                                                = Handle
                                                                                .Result;

                                                                                Dictionary
                                                                                [Path]
                                                                                = GameObject;
                                                                            }

                                                                            {
                                                                                JArray _JArray
                                                                                = new JArray();

                                                                                {
                                                                                    Dictionary<JToken, GameObject> _Dictionary
                                                                                    = @Environment_World_AddressablesQueue_Dictionary;

                                                                                    for (int i = 0; 
                                                                                    i < _Dictionary.Count; 
                                                                                    i++)
                                                                                    {
                                                                                        KeyValuePair
                                                                                        <JToken, GameObject> 
                                                                                        KeyValuePair
                                                                                        = _Dictionary
                                                                                        .ElementAt(i);

                                                                                        JToken JToken
                                                                                        = KeyValuePair
                                                                                        .Key;

                                                                                        _JArray
                                                                                        .Add(JToken);

                                                                                        GameObject GameObject
                                                                                        = KeyValuePair
                                                                                        .Value;

                                                                                        await UniTask
                                                                                        .WaitUntil(()
                                                                                        => isLocked
                                                                                        == false);

                                                                                        Destroy
                                                                                        (GameObject);

                                                                                        await UniTask
                                                                                        .WaitUntil(()
                                                                                        => GameObject
                                                                                        == null);
                                                                                    }
                                                                                }

                                                                                {
                                                                                    @Environment_World_Cancellation
                                                                                    = true;

                                                                                    await Environment_World_Task(
                                                                                    new JObject
                                                                                    {
                                                                                        ["Event"]
                                                                                        = "Object",

                                                                                        ["Array"]
                                                                                        = _JArray
                                                                                    });
                                                                                }

