                                                                                    = false;

                                                                                    await Environment_World_Task(
                                                                                    new JObject
                                                                                    {
                                                                                        ["Event"]
                                                                                        = "Culling"
                                                                                    });
                                                                                }
                                                                            }
                                                                        }
                                                                        break;
