                                            }

                                            GameObject
                                            .name
                                            = String;

                                            GameObject
                                            .transform
                                            .localScale
                                            = new Vector3
                                            (1, 1, 1);

                                            {
                                                Vector3 Vector3
                                                = new Vector3();

                                                {
                                                    Vector3
                                                    .x
                                                    = (float)
                                                    JToken
                                                    ["Position"]
                                                    ["X"];

                                                    Vector3
                                                    .y
                                                    = (float)
                                                    JToken
                                                    ["Position"]
                                                    ["Y"];

                                                    Vector3
                                                    .z
                                                    = (float)
