                                                = new Quaternion();

                                                {
                                                    Quaternion
                                                    .x
                                                    = (float)
                                                    JToken
                                                    ["Rotation"]
                                                    ["X"];

                                                    Quaternion
                                                    .y
                                                    = (float)
                                                    JToken
                                                    ["Rotation"]
                                                    ["Y"];

                                                    Quaternion
                                                    .z
                                                    = (float)
                                                    JToken
                                                    ["Rotation"]
                                                    ["Z"];
                                                }

                                                GameObject
                                                .transform
                                                .rotation
                                                = Quaternion;
                                            }

                                            {
                                                Vector3 Vector3
                                                = new Vector3();

                                                {
                                                    Vector3
                                                    .x
                                                    = (float)
                                                    JToken
                                                    ["Scale"]
                                                    ["X"];

                                                    Vector3
                                                    .y
                                                    = 0f;

                                                    Vector3
                                                    .z
                                                    = (float)
                                                    JToken
                                                    ["Scale"]
                                                    ["Z"];
                                                }

                                                GameObject
                                                .transform
                                                .localScale
                                                = Vector3;
                                            }

                                            {
                                                GameObject
                                                .transform.Find
                                                ("Label[Text]")
                                                .GetComponent
                                                <TextMeshPro>()
                                                .text
                                                = (string)
                                                JToken
                                                ["Label"];
                                            }

                                            GameObject
                                            .transform
                                            .SetAsLastSibling();

                                            GameObject
                                            .SetActive
                                            (true);

                                            {
                                                float DurationFloat
                                                = 0.3f;

                                                float ScaleFloat
                                                = (float)
                                                JToken
                                                ["Scale"]
                                                ["Y"];

                                                Vector3 StartScaleVector3
                                                = GameObject
                                                .transform
                                                .localScale;

                                                Vector3 EndScaleVector3
                                                = new Vector3(
                                                StartScaleVector3
                                                .x,
                                                ScaleFloat,
                                                StartScaleVector3
                                                .z);

                                                float TimeFloat
                                                = 0f;

                                                while (TimeFloat
                                                < DurationFloat)
                                                {
                                                    float LerpFloat
                                                    = TimeFloat
                                                    / DurationFloat;

                                                    LerpFloat
                                                    = Mathf
                                                    .SmoothStep
                                                    (0f, 1f,
                                                    LerpFloat);

                                                    GameObject
                                                    .transform
                                                    .localScale
                                                    = Vector3.Lerp(
                                                    StartScaleVector3,
                                                    EndScaleVector3,
                                                    LerpFloat);

                                                    TimeFloat
                                                    += Time
                                                    .deltaTime;

                                                    await UniTask
                                                    .Yield(
                                                    PlayerLoopTiming
                                                    .Update);
                                                }

                                                GameObject
                                                .transform
                                                .localScale
                                                = EndScaleVector3;
                                            }
                                        }
                                        break;
                                }

                                await UniTask
                                .Yield(PlayerLoopTiming
                                .LastPostLateUpdate);
                            }

                            isLocked
                            = false;
                        }
                    }
                    break;
                case "Culling":
                    {
                        Transform Transform
                        = Environment
                        .transform.Find
                        ("World[Object]")
                        .transform;

                        foreach (Transform _Transform
                        in Transform)
                        {
                            bool Boolean
                            = @Environment_World_Cancellation;

                            if (Boolean)
                            { break; }

                            float Y_Float
                            = Camera
                            .transform.Find
                            ("ViewportRect[Object]")
                            .transform.Find
                            ("UpperCenter[MeshFilter]")
                            .transform
                            .position
                            .y;

                            float YRange_Float
                            = Camera
                            .transform.Find
                            ("ViewportRect[Object]")
                            .transform.Find
                            ("BottomCenter[MeshFilter]")
                            .transform
                            .position
                            .y;

                            float X_Float
                            = Camera
                            .transform.Find
                            ("ViewportRect[Object]")
                            .transform.Find
                            ("MiddleLeft[MeshFilter]")
                            .transform
                            .position
                            .x;

                            float XRange_Float
                            = Camera
                            .transform.Find
                            ("ViewportRect[Object]")
                            .transform.Find
                            ("MiddleRight[MeshFilter]")
                            .transform
                            .position
                            .x;

                            {
                                Vector3 Vector3
                                = _Transform
                                .position;

                                Boolean
                                = (Y_Float
                                >= Vector3
                                .y

                                && YRange_Float
                                <= Vector3
                                .y


                                && X_Float
                                <= Vector3
                                .x

                                && XRange_Float
                                >= Vector3
                                .x)
                                == false;

                                switch (Boolean)
                                {
                                    case true:
                                        {
                                            GameObject GameObject
                                            = _Transform
                                            .gameObject;

                                            string String
                                            = GameObject
                                            .name;

                                            Boolean
                                            = String
                                            .StartsWith
                                            ("Template")
                                            == false;

                                            switch (Boolean)
                                            {
                                                case true:
                                                    {
                                                        Destroy
                                                        (GameObject);
                                                    }
                                                    break;
                                            }
                                        }
                                        break;
                                }
                            }

                            await UniTask
                            .Yield(PlayerLoopTiming
                            .LastPostLateUpdate);
                        }
                    }
                    break;
            }
        }
        catch (Exception Exception)
        {
#if DEBUG
            Debug
            .LogError
            (Exception);
#endif
        }

        Environment_World_Cancellation
        = false;
    }

