                .transform.Find("Panel[Object]")
                .transform;

                foreach (Transform _Transform
                in Transform)
                {
                    bool Boolean
                    = Widget_Panel_Accessibility_Panel_Operations_Inventory_Function_Cancellation;

                    if (Boolean)
                    { break; }

                        string String
                        = _Transform
                        .gameObject
                        .name;

                        String
                        = String
                        .Replace(
                        "[Object]", 
                        String
                        .Empty);

                        String
                        = String
                        .ToLower();

                        Boolean
                        = String
                        .Contains
                        ((string)
                        Dictionary
                        ["Search"]);

                        _Transform
                        .gameObject
                        .SetActive
                        (Boolean);
                }
            }
            break;
        }
