    private async UniTask Start()
    {
        {
            {
                {
                    Transform Transform
                    = Canvas
                    .transform.Find("Widget[Object]")
                    .transform.Find("Panel[Object]")
                    .transform.Find("Keyboard[Object]")
                    .transform;

                    {
                        foreach (Transform _Transform
                        in new Transform[]
                        {
                            Transform.Find("Content[Object]")
                            .transform.Find("Key[Object]")
                            .transform.Find("Alpha[Object]")
                            .transform,

                            Transform.Find("Content[Object]")
                            .transform.Find("Numic[Object]")
                            .transform
                        })
                        {
                            int Columns
                            = _Transform
                            .childCount;

                            for (int i = 0; i < Columns; i++)
                            {
                                Transform
                                = _Transform
                                .GetChild(i);

                                string String
                                = Transform
                                .gameObject
                                .name;

                                {
                                    StringBuilder StringBuilder
                                    = new StringBuilder(String);

                                    StringBuilder
                                    .Replace(
                                    "[Button]",
                                    String.Empty);

                                    String
                                    = StringBuilder
                                    .ToString();
                                }

                                {
                                    bool Boolean
                                    = String
                                    .Any(
                                    x =>
                                    char.IsLetter(x)
                                    || char.IsDigit(x)
                                    || char.IsSymbol(x)
                                    || char.IsPunctuation(x))

                                    && String
                                    .Length
                                    == 1;

                                    switch (Boolean)
                                    {
                                        case true:
                                            {
                                                KeyboardKeyList
                                                .Add(Transform);

                                                char Char
                                                = String
                                                .ToCharArray()
                                                .FirstOrDefault();

                                                Transform
                                                .GetComponent<Button>()
                                                .onClick.AddListener(() =>
                                                {
                                                    TMP_InputField TMP_InputField
                                                    = Canvas
                                                    .transform.Find("Widget[Object]")
                                                    .transform.Find("Panel[Object]")
                                                    .transform.Find("Keyboard[Object]")
                                                    .transform.Find("Label[Input]")
                                                    .transform.Find("Input[InputField]")
                                                    .GetComponent<TMP_InputField>();

                                                    TMP_InputField
                                                    .text += Char;
                                                });

                                            }
                                            break;
                                    }
                                }

                                {
                                    if (i % 100 == 0)
                                    {
                                        await UniTask
                                        .Yield(
                                        PlayerLoopTiming
                                        .Update);
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }

        await
        Manage();
    }

