    private async UniTask StructTask(
    List<KeyValuePair<string, object>> PList)
    {
        foreach (
        KeyValuePair<string, object> KeyValuePair in
        PList)
        {
            switch (KeyValuePair.Key)
            {
                case "Directory":
                    {
                        string Path
                        = (string)KeyValuePair.Value;
                        Directory
                        .CreateDirectory(Path);
                    }
                    break;
                case "File":
                    {
                        string Path
                        = (string)KeyValuePair
                        .Value;

                        switch (
                        File.Exists(Path)
                        == false)
                        {
                            case true:
                                using (File.Create(Path)) { }
                                break;
                        }
                    }
                    break;
                case "Json":
                    {
                        KeyValuePair<string, JObject> _KeyValuePair
                        = (KeyValuePair<string, JObject>)KeyValuePair.Value;

                        string Path
                        = _KeyValuePair.Key;

                        bool Boolean
                        = File.Exists(Path)
                        == false;

                        switch (Boolean)
                        {
                            case true:
                                await File.WriteAllTextAsync(Path,
                                new JObject()
                                .ToString(
                                Formatting
                                .None));
                                break;
                        }

                        JObject JObject
                        = _KeyValuePair.Value;

                        string String
                        = await File.ReadAllTextAsync(Path);

                        JObject _JObject
                        = JObject.Parse(String);

                        JObject.Merge(_JObject,
                        new JsonMergeSettings
                        {
                            MergeArrayHandling = MergeArrayHandling.Replace,
                            MergeNullValueHandling = MergeNullValueHandling.Merge
                        });

                        await File.WriteAllTextAsync(Path,
                        JObject.ToString(
                        Formatting
                        .Indented));
                    }
                    break;
                case "Json-List":
                    {
                        KeyValuePair<string, JObject> _KeyValuePair
                        = (KeyValuePair<string, JObject>)KeyValuePair.Value;

                        string Path
                        = _KeyValuePair.Key;

                        FileInfo FileInfo
                        = new FileInfo(Path);

                        Array Array
                        = await File.ReadAllLinesAsync(Path);

                        foreach (
                        string String in
                        Array)
                        {
                            Guid Guid
                            = Guid.Parse(String);

                            JObject JObject
                            = _KeyValuePair.Value;

                            string _Path
                            = FileInfo.DirectoryName +
                            "/" +
                            Guid;

                            string _String
                            = await File.ReadAllTextAsync(_Path);

                            JObject _JObject
                            = JObject.Parse(_String);

                            JObject
                            .Merge(_JObject,
                            new JsonMergeSettings
                            {
                                MergeArrayHandling
                                = MergeArrayHandling
                                .Merge,
                                MergeNullValueHandling
                                = MergeNullValueHandling
                                .Merge,
                            });

                            await File.WriteAllTextAsync(_Path,
                            JObject.ToString(
                            Formatting
                            .Indented));
                        }
                    }
                    break;
            }
        }
    }

    JObject ManageJObject
    = new JObject
    {
        ["Data"]
        = "/indus/data",

        ["Info"]
        = new JObject()
    };
    private async UniTask Manage()
    {
#if UNITY_EDITOR
        {
            StringBuilder StringBuilder
            = new StringBuilder();

            StringBuilder
            .Append(
            Application.dataPath);

            StringBuilder
            .Append("/.Data");

            string Path
            = StringBuilder
            .ToString();

            ManageJObject["Data"]
            = Path;
        }
#endif

        Transform Transform
        = Canvas
        .transform.Find("Interface[Object]")
        .transform.Find("Sequence[Object]")
        .transform.Find("Panel[Object]")
        .transform;

        {
            Transform
            .gameObject
            .SetActive(true);

            await Rebind
            (Transform);

            Animator Animator
            = Transform
            .GetComponent<Animator>();

            await Animate
            (Animator);
        }

        Slider Slider
        = Transform.Find("List[Object]")
        .transform.Find("Progress[Object]")
        .transform.Find("Slider")
        .GetComponent<Slider>();

        {
            Array Array
            = new UniTask[]
            {
                UniTask
                .RunOnThreadPool(
                async () =>
                {
                    await StructTask(
                    new List<KeyValuePair<string, object>>
                    {
                        new KeyValuePair<string, object>(
                        "Directory",
                            (string)ManageJObject["Data"] +
                            "/Language"),

                        new KeyValuePair<string, object>(
                        "Directory",
                            (string)ManageJObject["Data"] +
                            "/Internet"),

                        new KeyValuePair<string, object>(
                        "Json",
                            new KeyValuePair<string, JObject>(
                            (string)ManageJObject["Data"] +
                            "/.Info",
                            new JObject
                            {
                                ["Lang"]
                                = "English",

                                ["Set"]
                                = false
                            }))
                    });
                }),


                UniTask
                .RunOnThreadPool(
                async () =>
                {
                    string Path
                    = (string)ManageJObject["Data"] +
                    "/.Info";

                    string String
                    = await File
                    .ReadAllTextAsync(Path);

                    JToken JToken
                    = JToken.Parse(String);

                    ManageJObject["Info"]
                    = JToken;
                }),
            };

            int Columns
            = Array.Length;

            Slider
            .maxValue
            = Columns;

            Slider
            .wholeNumbers
            = true;

            for (
            int i = 0; i < Columns; i++)
            {
                UniTask UniTask
                = (UniTask)Array
                .GetValue(i);

                await
                UniTask;

                Slider
                .value++;
            }
        }

        {
            {
                Transform
                = Canvas
                .transform;

                Transform
                = Transform.Find("Activity[Object]")
                .transform;

                Transform
                .gameObject
                .SetActive(true);
            }

            {
                Transform
                = Canvas
                .transform.Find("Interface[Object]")
                .transform;

                foreach (Transform _Transform
                in Transform)
                {
                    _Transform
                    .gameObject
                    .SetActive(false);
                }

                {
                    Transform
                    = Transform.Find("Options[Object]")
                    .transform;

                    Transform
                    .gameObject
                    .SetActive(true);

                    await Rebind
                    (Transform);

                    Animator Animator
                    = Transform
                    .GetComponent<Animator>();

                    await Animate
                    (Animator);
                }

                {
                    Transform
                    = Transform.Find("Panel[Object]")
                    .transform.Find("List[Object]")
                    .transform;

                    foreach (Transform _Transform
                    in Transform)
                    {
                        string String
                        = _Transform
                        .gameObject.name;

                        bool Boolean
                        = String ==
                        "Splash[Object]";

                        _Transform
                        .gameObject
                        .SetActive(Boolean);
                    }

                    {
                        Transform
                        = Transform.Find("Language[Object]")
                        .transform;

                        Transform
                        .gameObject
                        .SetActive(true);

                        await Rebind
                        (Transform);

                        Animator Animator
                        = Transform
                        .GetComponent<Animator>();

                        await Animate
                        (Animator);

                        {
                            Widget_Language_Cancellation
                            = true;

                            await Widget_Language_Task(
                            new JObject
                            {
                                ["Event"]
                                = "List"
                            });
                        }
                    }
                }
            }
        }
    }

    List<Transform> KeyboardKeyList
    = new List<Transform>();
    private async UniTask Keyboard(
    TMP_InputField TMP_InputField
    )
    {
        Transform Transform
        = Canvas
        .transform.Find("Widget[Object]")
        .transform.Find("Panel[Object]")
        .transform;

        Transform ActiveWidgetTransform
        = null;

        foreach (Transform _Transform
        in Transform)
        {
            {
                bool Boolean
                = _Transform
                .gameObject
                .activeSelf;

                switch (Boolean)
                {
                    case true:
                        {
                            ActiveWidgetTransform
                            = _Transform;
                        }
                        break;
                }
            }

            {
                _Transform
                .gameObject
                .SetActive(false);
            }
        }

        {
            Transform
            = Transform
            .transform.Find("Keyboard[Object]")
            .transform;

            Transform
            .gameObject
            .SetActive(true);

            {
                Transform.Find("Label[Input]")
                .transform.Find("Input[InputField]")
                .GetComponent<TMP_InputField>()
                .placeholder
                .GetComponent<TextMeshProUGUI>()
                .text = TMP_InputField
                .placeholder
                .GetComponent<TextMeshProUGUI>()
                .text;

                Transform.Find("Label[Input]")
                .transform.Find("Input[InputField]")
                .GetComponent<TMP_InputField>()
                .text = TMP_InputField.text;
            }

            {
                await Rebind
                (Transform);

                Animator Animator
                = Transform
                .GetComponent<Animator>();

                await Animate
                (Animator);
            }
        }

        {
            foreach (Transform _Transform
                in KeyboardKeyList)
            {
                string String
                = _Transform
                .gameObject
                .name;

                StringBuilder StringBuilder
                = new StringBuilder(String);

                StringBuilder
                .Replace(
                "[Button]"
                , String.Empty);

                String
                = StringBuilder
                .ToString();

                {
                    bool Boolean
                    = false;

                    switch (
                    TMP_InputField
                    .contentType)
                    {
                        case TMP_InputField
                        .ContentType
                        .Name:
                            {
                                Boolean
                                = String
                                .Any(
                                x =>
                                char.IsLetter(x));
                            }
                            break;
                        case TMP_InputField
                        .ContentType
                        .Alphanumeric:
                            {
                                Boolean
                                = String
                                .Any(
                                x =>
                                char.IsLetter(x)
                                || char.IsNumber(x));
                            }
                            break;
                        case TMP_InputField
                        .ContentType
                        .IntegerNumber:
                            {
                                Boolean
                                = String
                                .Any(
                                x =>
                                char.IsNumber(x));
                            }
                            break;
                        case TMP_InputField
                            .ContentType
                            .DecimalNumber:
                            {
                                Boolean
                                = String
                                .Any(
                                x =>
                                char.IsNumber(x)
                                || x == '.');
                            }
                            break;
                    }

                    Button Button
                    = _Transform
                    .GetComponent<Button>();

                    Button
                    .interactable
                    = Boolean;
                }
            }
        }

        {
            {
                while (
                Transform
                .gameObject
                .activeSelf)
                {
                    await UniTask
                    .NextFrame();
                }

                TMP_InputField.text
                = Transform.Find("Label[Input]")
                .transform.Find("Input[InputField]")
                .GetComponent<TMP_InputField>()
                .text;
            }

            {
                bool Boolean
                = ActiveWidgetTransform
                != null;

                switch (Boolean)
                {
                    case true:
                        {
                            ActiveWidgetTransform
                            .gameObject
                            .SetActive(true);
                        }
                        break;
                }
            }
        }
    }

    private bool Widget_Language_Cancellation
    = false;

    private async UniTask Widget_Language_Task(
    JToken PJToken
    )
    {
        Widget_Language_Cancellation
        = false;

        switch (
        (string)
        PJToken
        ["Event"])
        {
            case "List":
                {
                    Transform Transform
                    = Canvas
                    .transform.Find("Widget[Object]")
                    .transform.Find("Panel[Object]")
                    .transform.Find("Language[Object]")
                    .transform.Find("List[Object]")
                    .transform.Find("Content[Object]")
                    .transform.Find("List[Scroll-View]")
                    .GetComponent<ScrollRect>()
                    .content
                    .transform;

                    StringBuilder StringBuilder
                    = new StringBuilder();

                    StringBuilder
                    .Append(
                    Application.dataPath);
                    StringBuilder
                    .Append("/.Data");
                    StringBuilder
                    .Append("/Language");

                    string Path
                    = StringBuilder
                    .ToString();

                    Array Array
                    = Directory
                    .GetFiles(
                    Path,
                    "*.*",
                    SearchOption
                    .TopDirectoryOnly)
                    .Where(
                    x =>
                    x.EndsWith
                    (".Template")
                    == false)
                    .ToArray();

                    int Columns
                    = Array
                    .Length;

                    IEnumerable<Transform>
                    IEnumerable
                    = Transform
                    .GetComponentsInChildren<Transform>
                    (false)
                    .Where
                    (x =>
                    x.gameObject
                    .name
                    .EndsWith(
                    "[Button]"));

                    int Index
                    = IEnumerable
                    .Count();

                    int Incre
                    = 6;

                    int Length
                    = Index
                    + Incre;

                    Columns
                    = Math.Min
                    (
                    Length,
                    Columns);

                    for (
                    int i = Index;
                    i < Columns;
                    i++)
                    {
                        if (Widget_Language_Cancellation)
                        { break; }

                        Path
                        = (string)
                        Array
                        .GetValue(i);

                        FileInfo FileInfo
                        = new FileInfo(Path);

                        {
                            StringBuilder
                            = new StringBuilder();

                            string String
                            = FileInfo
                            .Name;

                            StringBuilder
                            .Append(String);
                            StringBuilder
                            .Append("[Button]");

                            String
                            = StringBuilder
                            .ToString();

                            bool Boolean
                            = Transform.Find(String)
                            == null;

                            switch (Boolean)
                            {
                                case true:
                                    {
                                        Transform
                                        .Find("Progress[Object]")
                                        .gameObject
                                        .SetActive(true);

                                        GameObject GameObject
                                        = Instantiate(
                                        Transform
                                        .Find("Template[Button]")
                                        .gameObject,
                                        Transform
                                        );

                                        Index
                                        = Transform
                                        .Find("Progress[Object]")
                                        .transform
                                        .GetSiblingIndex();

                                        GameObject
                                        .transform
                                        .SetSiblingIndex(Index);

                                        GameObject
                                        .transform
                                        .localScale
                                        = new Vector3(1, 1, 1);

                                        GameObject
                                        .name
                                        = String;

                                        String
                                        = FileInfo
                                        .Name;

                                        GameObject
                                        .transform.Find("Label[Text]")
                                        .GetComponent<TextMeshProUGUI>()
                                        .text
                                        = String;

                                        GameObject
                                        .GetComponent<Button>()
                                        .onClick.AddListener(async () =>
                                        {
                                            {
                                                Transform Transform
                                                = Canvas
                                                .transform.Find("Widget[Object]")
                                                .transform.Find("Panel[Object]")
                                                .transform;

                                                foreach (Transform _Transform
                                                in Transform)
                                                {
                                                    _Transform
                                                    .gameObject
                                                    .SetActive(false);
                                                }
                                            }

                                            {
                                                Transform Transform
                                                = Canvas
                                                .transform.Find("Interface[Object]")
                                                .transform.Find("Options[Object]")
                                                .transform.Find("Panel[Object]")
                                                .transform.Find("List[Object]")
                                                .transform;

                                                foreach (Transform _Transform
                                                in Transform)
                                                {
                                                    string String
                                                    = _Transform
                                                    .gameObject.name;

                                                    bool Boolean
                                                    = String ==
                                                    "Splash[Object]";

                                                    _Transform
                                                    .gameObject
                                                    .SetActive(Boolean);
                                                }

                                                {
                                                    Transform
                                                    = Transform.Find("TimeZone[Object]")
                                                    .transform;

                                                    Transform
                                                    .gameObject
                                                    .SetActive(true);

                                                    {
                                                        await Rebind
                                                        (Transform);

                                                        Animator Animator
                                                        = Transform
                                                        .GetComponent<Animator>();

                                                        await Animate
                                                        (Animator);
                                                    }
                                                }
                                            }

                                            {
                                                Widget_TimeZone_Cancellation
                                                = true;

                                                await Widget_TimeZone_Task(
                                                new JObject
                                                {
                                                    ["Event"]
                                                    = "List"
                                                });
                                            }

                                            {
                                                Widget_Language_Cancellation
                                                = true;

                                                await Widget_Language_Task(
                                                new JObject
                                                {
                                                    ["Event"]
                                                    = "Set",

                                                    ["Lang"]
                                                    = String
                                                });
                                            }
                                        });

                                        GameObject
                                        .SetActive(true);

                                        {
                                            Animator Animator
                                            = GameObject
                                            .GetComponent<Animator>();

                                            await Animate
                                            (Animator);
                                        }

                                        Transform
                                        .Find("Progress[Object]")
                                        .gameObject
                                        .SetActive(false);
                                    }
                                    break;
                            }
                        }

                        {
                            if (i % 100 == 0)
                            {
                                await UniTask
                                .Yield(
                                PlayerLoopTiming
                                .Update);
                            }
                        }
                    }
                }
                break;
            case "Set":
                {
                    StringBuilder StringBuilder
                    = new StringBuilder();

                    StringBuilder
                    .Append(
                    Application.dataPath);
                    StringBuilder
                    .Append("/.Data");
                    StringBuilder
                    .Append("/Language/");

                    string String
                    = (string)
                    PJToken["Lang"];

                    StringBuilder
                    .Append(String);

                    ManageJObject
                    ["Info"]
                    ["Lang"]
                    = String;

                    string Path
                    = StringBuilder
                    .ToString();

                    String
                    = await File
                    .ReadAllTextAsync(Path);

                    JObject JObject
                    = JObject
                    .Parse(String);

                    IEnumerable
                    <TextMeshProUGUI> IEnumerable
                    = Canvas
                    .GetComponentsInChildren
                    <TextMeshProUGUI>(true);

                    {
                        int Delay
                        = 0;
                        foreach (
                        TextMeshProUGUI
                        TextMeshProUGUI
                        in IEnumerable)
                        {
                            if (Widget_Language_Cancellation)
                            { break; }

                            String
                            = TextMeshProUGUI
                            .text;

                            bool Boolean
                            = new string[]
                            {
                            "Title",
                            "Label",
                            "Text"
                            }.Any(
                            x =>
                            x ==
                            String)
                            == false

                            && String
                            .All(
                            x =>
                            char
                            .IsLetter(x)

                            || char
                            .IsWhiteSpace(x))

                            && String
                            .Length > 0;

                            switch (Boolean)
                            {
                                case true:
                                    {
                                        byte[] Bytes
                                        = Encoding.
                                        UTF8.GetBytes(String);

                                        Bytes
                                        = XxHash64
                                        .Hash(Bytes);

                                        string Index
                                        = Convert
                                        .ToBase64String(Bytes);

                                        Boolean
                                        = JObject
                                        .ContainsKey(Index);

                                        switch (Boolean)
                                        {
                                            case true:
                                                {
                                                    JToken JToken
                                                    = JObject[Index];

                                                    String
                                                    = (string)JToken;

                                                    TextMeshProUGUI
                                                    .text
                                                    = String;
                                                }
                                                break;
                                        }
                                    }
                                    break;
                            }

                            {
                                if (++Delay % 100 == 0)
                                {
                                    await UniTask
                                    .Yield(
                                    PlayerLoopTiming
                                    .Update);
                                }
                            }
                        }
                    }
                }
                break;
        }
    }

    private bool Widget_TimeZone_Cancellation
    = false;

    private async UniTask Widget_TimeZone_Task(
    JToken PJToken
    )
    {
        Widget_TimeZone_Cancellation
        = false;

        switch (
        (string)
        PJToken
        ["Event"])
        {
            case "Search":
                {
                    Transform Transform
                    = Canvas
                    .transform.Find("Widget[Object]")
                    .transform.Find("Panel[Object]")
                    .transform.Find("TimeZone[Object]")
                    .transform.Find("List[Object]")
                    .transform.Find("Content[Object]")
                    .transform.Find("List[Scroll-View]")
                    .GetComponent<ScrollRect>()
                    .content
                    .transform;

                    foreach (Transform _Transform
                    in Transform)
                    {
                        if (Widget_TimeZone_Cancellation)
                        { break; }

                        _Transform
                        .gameObject
                        .SetActive(false);
                    }

                    IEnumerable
                    <CSystem.Timezone.Zone> IEnumerable
                    = await
                    Timezone
                    .GetZones();

                    string String
                    = (string)PJToken["Index"];

                    // here
                    CSystem
                    .Timezone
                    .Zone Zone
                    = IEnumerable
                    .Where(
                    x =>
                    x.ID
                    == String
                    ).FirstOrDefault();

                    Widget_TimeZone_Cancellation
                    = true;

                    await Widget_TimeZone_Task
                    (Zone);
                }
                break;
            case "List":
                {
                    Transform Transform
                    = Canvas
                    .transform.Find("Widget[Object]")
                    .transform.Find("Panel[Object]")
                    .transform.Find("TimeZone[Object]")
                    .transform.Find("List[Object]")
                    .transform.Find("Content[Object]")
                    .transform.Find("List[Scroll-View]")
                    .GetComponent<ScrollRect>()
                    .content
                    .transform;

                    Array Array
                    = await
                    Timezone
                    .GetZones();

                    int Columns
                    = Array
                    .Length;

                    IEnumerable<Transform>
                    IEnumerable
                    = Transform
                    .GetComponentsInChildren<Transform>
                    (false)
                    .Where
                    (x =>
                    x.gameObject
                    .name
                    .EndsWith(
                    "[Button]"));

                    int Index
                    = IEnumerable
                    .Count();

                    int Incre
                    = 5;

                    int Length
                    = Index
                    + Incre;

                    Columns
                    = Math.Min
                    (
                    Length,
                    Columns);

                    for (
                    int i = Index;
                    i < Columns;
                    i++)
                    {
                        if (Widget_TimeZone_Cancellation)
                        { break; }

                        CSystem
                        .Timezone.Zone Zone
                        = (CSystem.Timezone.Zone)
                        Array.GetValue(i);

                        await Widget_TimeZone_Task
                        (Zone);

                        {
                            if (i % 100 == 0)
                            {
                                await UniTask
                                .Yield(
                                PlayerLoopTiming
                                .Update);
                            }
                        }
                    }
                }
                break;
        }
    }

