#endif

    private async UniTask Rebind(
    Transform Transform
    )
    {
        await UniTask
        .NextFrame();

        RectTransform RectTransform
        = Transform
        .GetComponent<RectTransform>();

        LayoutRebuilder
        .ForceRebuildLayoutImmediate
        (RectTransform);
    }

    private async UniTask Animate(
    Animator Animator
    )
    {
        Animator.enabled
        = true;

        int Columns
        = Animator
        .layerCount;

        for (int i = 0; i < Columns; i++)
        {
            await UniTask.WaitUntil(() =>
            Animator
            .GetCurrentAnimatorStateInfo(i)
            .normalizedTime > 1);
        }

        Animator.enabled
        = false;
    }
